:root {
  --bg: #2b2d42;
  --card-bg: #edf2f4;
  --text: #2b2d42;
  --accent: #ef233c;
  --accent-hover: #d90429;
  --bar-bg: #8d99ae;
  --hunger-color: #f4a261;
  --happiness-color: #e76f51;
  --energy-color: #2a9d8f;
  --focus: #ffd166;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-card {
  background: var(--card-bg);
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.3);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--text);
}

.pet-container {
  width: 120px;
  height: 120px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.pet {
  width: 80px;
  height: 80px;
  background: #f4a261;
  border-radius: 16px;
  position: relative;
  image-rendering: pixelated;
  box-shadow: inset -4px -4px 0 rgba(0, 0, 0, 0.15);
}

.pet-body {
  width: 100%;
  height: 100%;
  position: relative;
}

.pet-eye {
  width: 12px;
  height: 12px;
  background: #2b2d42;
  border-radius: 2px;
  position: absolute;
  top: 24px;
}

.pet-eye.left {
  left: 16px;
}

.pet-eye.right {
  right: 16px;
}

.pet-mouth {
  width: 24px;
  height: 8px;
  background: #2b2d42;
  border-radius: 0 0 8px 8px;
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
}

.mood {
  font-size: 1.125rem;
  font-weight: 600;
  text-align: center;
  color: var(--text);
  min-height: 1.5em;
}

.stats {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stat-row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.stat-label {
  width: 80px;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
}

.bar-container {
  flex: 1;
  height: 20px;
  background: var(--bar-bg);
  border-radius: 10px;
  overflow: hidden;
  position: relative;
}

.bar-fill {
  height: 100%;
  width: 80%;
  border-radius: 10px;
  transition: width 0.3s ease;
}

.bar-fill.hunger {
  background: var(--hunger-color);
}

.bar-fill.happiness {
  background: var(--happiness-color);
}

.bar-fill.energy {
  background: var(--energy-color);
}

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  flex-wrap: wrap;
  justify-content: center;
}

.btn {
  flex: 1;
  min-width: 100px;
  padding: 14px 16px;
  font-size: 1rem;
  font-weight: 700;
  font-family: inherit;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  letter-spacing: 0.5px;
}

.btn:hover {
  background: var(--accent-hover);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.btn:active {
  transform: scale(0.96);
}

.btn.feed {
  background: var(--hunger-color);
  color: #2b2d42;
}

.btn.feed:hover {
  background: #e08c4a;
}

.btn.play {
  background: var(--happiness-color);
}

.btn.play:hover {
  background: #d65d3f;
}

.btn.sleep {
  background: var(--energy-color);
}

.btn.sleep:hover {
  background: #248a7e;
}

@media (max-width: 400px) {
  .game-card {
    padding: 24px 16px;
    gap: 20px;
  }

  h1 {
    font-size: 1.5rem;
  }

  .stat-label {
    width: 70px;
    font-size: 0.9rem;
  }

  .btn {
    min-width: 80px;
    padding: 12px 12px;
    font-size: 0.95rem;
  }
}

const stats = {
  hunger: 80,
  happiness: 80,
  energy: 80
};

const moodText = document.getElementById('mood-text');
const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');
const hungerContainer = document.getElementById('hunger-bar-container');
const happinessContainer = document.getElementById('happiness-bar-container');
const energyContainer = document.getElementById('energy-bar-container');

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateMood() {
  const avg = (stats.hunger + stats.happiness + stats.energy) / 3;
  let mood;
  if (avg >= 70) mood = 'Your pet is feeling great!';
  else if (avg >= 40) mood = 'Your pet is doing okay.';
  else if (avg >= 20) mood = 'Your pet needs some attention...';
  else mood = 'Your pet is not feeling well. Please help!';
  moodText.textContent = mood;
}

function updateBars() {
  hungerBar.style.width = stats.hunger + '%';
  happinessBar.style.width = stats.happiness + '%';
  energyBar.style.width = stats.energy + '%';

  hungerContainer.setAttribute('aria-valuenow', stats.hunger);
  happinessContainer.setAttribute('aria-valuenow', stats.happiness);
  energyContainer.setAttribute('aria-valuenow', stats.energy);

  hungerContainer.textContent = stats.hunger;
  happinessContainer.textContent = stats.happiness;
  energyContainer.textContent = stats.energy;

  updateMood();
}

function feed() {
  stats.hunger = clamp(stats.hunger + 20);
  stats.energy = clamp(stats.energy - 5);
  updateBars();
}

function play() {
  stats.happiness = clamp(stats.happiness + 20);
  stats.energy = clamp(stats.energy - 15);
  stats.hunger = clamp(stats.hunger - 10);
  updateBars();
}

function sleep() {
  stats.energy = clamp(stats.energy + 30);
  stats.hunger = clamp(stats.hunger - 5);
  stats.happiness = clamp(stats.happiness - 5);
  updateBars();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

updateBars();
